U.add('arch','backup',{sev:1.85,ax:{n:.45,v:.3},new:'previous pages can be restored from backup, and come back corrupted',titles:['Restore from backup','Backup manager','Recovery','Previous versions'],build:c=>{const p=U.past(c).slice(-5);return '<p>Select a page to restore. Restoring is not undoable.</p>'+(p.length?p:[{t:'(nothing)',k:0}]).map((h,i)=>`<div class=row><button class=rs data-t="${U.esc(h.t)}" data-i2=${i}>restore</button> page_${String(h.k).padStart(4,'0')}.bak ${(c.r(30+i)*90+1).toFixed(1)}K</div>`).join('')+'<pre class=pv style="min-height:40px"></pre>'},after:c=>{c.w.querySelectorAll('.rs').forEach(b=>b.onclick=()=>{const t=b.dataset.t||'',r=i=>c.r(60+i+t.length);c.w.querySelector('.pv').textContent='restored: '+[...t].map((x,i)=>r(i)<.3?U.pick(['█','?','▒',' '],r(i+99)):x).join('')+'\n(also restored: '+U.you(r(3))+')'})}});
