U.add('snd','clicktone',{sev:1.5,ax:{a:.25},new:'reacts to clicks: every click plucks a string pitched by where on the screen you clicked',play:(a,o,r)=>{const R=U.au.rig(a),x=R.osc('sine',55),g=a.createGain();g.gain.value=.06;x.connect(g).connect(o);x.start();R.on(document,'pointerdown',e=>U.au.pluck(a,o,U.au.hz(110,Math.floor(Math.max(0,Math.min(.99,e.clientX/innerWidth))*8)),.3));return R.stop}});
U.add('snd','fanwind',{sev:1.5,play:(a,o,r)=>{const n=a.createBufferSource(),b=a.createBuffer(1,a.sampleRate*2,a.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;n.buffer=b;n.loop=true;const f=a.createBiquadFilter(),g=a.createGain(),l=a.createOscillator(),lg=a.createGain();f.type='lowpass';f.frequency.value=300+r(300)*300;g.gain.value=.08;lg.gain.value=.07;l.frequency.value=5+r(301)*3;l.frequency.linearRampToValueAtTime(.4,a.currentTime+90);l.connect(lg).connect(g.gain);n.connect(f).connect(g).connect(o);n.start();l.start();return()=>{n.stop();l.stop()}}});
U.add('snd','hoverbell',{sev:1.64,ax:{a:.3},new:'reacts to hover: an FM bell whose pitch comes from the length of the label under the pointer',play:(a,o,r)=>{const R=U.au.rig(a),x=R.osc('sine',82),g=a.createGain();g.gain.value=.05;x.connect(g).connect(o);x.start();R.on(document,'mouseover',e=>{const t=e.target&&e.target.closest&&e.target.closest('button,a,input,select,label');if(!t)return;const n=(t.textContent||t.value||'').length;U.au.bell(a,o,U.au.hz(220,n),.12,1.4+(n%3)*.3,2,1.6)});return R.stop}});
U.add('snd','keyorgan',{sev:1.92,ax:{a:.4},new:'reacts to your typing: pitch from each character, note length from how fast you type',play:(a,o,r)=>{const R=U.au.rig(a),x=R.osc('sine',65),g=a.createGain();let last=0;g.gain.value=.05;x.connect(g).connect(o);x.start();R.on(document,'keydown',e=>{const t=e.target;if(!t||!/INPUT|TEXTAREA/.test(t.tagName)||!e.key||e.key.length!=1)return;const n=Date.now(),dt=n-last,s=a.currentTime,v=a.createOscillator(),ev=a.createGain(),d=dt<150?.18:.6;last=n;v.type='triangle';v.frequency.value=U.au.hz(147,e.key.charCodeAt(0));ev.gain.setValueAtTime(.0001,s);ev.gain.linearRampToValueAtTime(.14,s+.01);ev.gain.exponentialRampToValueAtTime(.0001,s+d);v.connect(ev).connect(o);v.start(s);v.stop(s+d+.05)});return R.stop}});
U.add('snd','lastword',{sev:1.9,play:(a,o,r)=>{const f0=180+r(300)*120,t=setInterval(()=>{const x=a.createOscillator(),g=a.createGain(),s=a.currentTime;x.type='triangle';x.frequency.setValueAtTime(f0,s);x.frequency.exponentialRampToValueAtTime(f0*.5,s+.6);g.gain.setValueAtTime(.001,s);g.gain.linearRampToValueAtTime(.08,s+.1);g.gain.exponentialRampToValueAtTime(.001,s+.7);x.connect(g).connect(o);x.start(s);x.stop(s+.8)},7000+r(301)*5000);return()=>clearInterval(t)}});
